import unittest


def count_upper(s):
    count = 0
    for i in range(0, len(s), 2):
        if s[i] in "AEIOU":
            count += 1
    return count


class TestCountUpper(unittest.TestCase):

    def test_empty_string(self):
        self.assertEqual(count_upper(""), 0)

    def test_single_upper_vowel_even_index(self):
        self.assertEqual(count_upper("A"), 1)

    def test_single_lower_vowel_even_index(self):
        self.assertEqual(count_upper("a"), 0)

    def test_mixed_case_vowels(self):
        self.assertEqual(count_upper("aBCdEf"), 1)

    def test_alternating_upper_vowels(self):
        self.assertEqual(count_upper("abcdefg"), 0)

    def test_all_upper_vowels_even_indices(self):
        self.assertEqual(count_upper("AEIOU"), 3)  # A, I, U at even indices

    def test_vowels_at_odd_indices(self):
        self.assertEqual(count_upper("bAcEdIfOgU"), 0)  # vowels at odd indices only

    def test_no_vowels(self):
        self.assertEqual(count_upper("bcdfg"), 0)

    def test_upper_vowels_mixed_positions(self):
        self.assertEqual(count_upper("AbE"), 1)  # A at index 0

    def test_string_with_digits_and_vowels(self):
        self.assertEqual(count_upper("A1E3I5O7U"), 3)

    def test_long_string(self):
        self.assertEqual(count_upper("AEIOU" * 3), 9)

    def test_only_consonants_upper(self):
        self.assertEqual(count_upper("BCDFG"), 0)

    def test_y_is_not_counted(self):
        self.assertEqual(count_upper("Y"), 0)

    def test_upper_vowels_second_half(self):
        self.assertEqual(count_upper("xyzAEIOU"), 1)  # only A at index 3? no—E at index 4 counts

    def test_whitespace_string(self):
        self.assertEqual(count_upper(" "), 0)


if __name__ == "__main__":
